#include <stdio.h>
#include <math.h>
/* ex01：奈奎斯特定理——无噪声信道的极限速率
 * C = 2W·log2(V)，W 为带宽(Hz)，V 为码元离散电平数。
 * 关键点：带宽定「最高能抖动多少次」，电平数定「每次能载几个比特」。
 * 注意 2W 而不是 W：一个周期能表示两个码元（正半周 + 负半周）。*/
int main(void) {
    double W = 3000.0;                 /* 话音频带 3kHz */
    int    V[] = {2, 4, 8, 16};        /* 电平数：2/4/8/16 */

    printf("奈奎斯特：C = 2W·log2(V)，W = %.0f Hz\n", W);
    printf("--------------------------------------------------\n");
    printf("%-10s %-14s %-16s %s\n", "电平数V", "每码元比特", "极限速率 C", "相当于");
    for (int i = 0; i < 4; i++) {
        double bits = log2((double)V[i]);
        double C = 2.0 * W * bits;
        printf("%-10d %-14.0f %-16.0f %s\n", V[i], bits, C,
               V[i] == 2 ? "NRZ 二电平" : V[i] == 4 ? "QPSK" : V[i] == 8 ? "8-PSK" : "16-QAM");
    }
    printf("--------------------------------------------------\n");
    printf("读法：带宽不变时，把电平数从 2 提到 16（4 倍比特/码元），\n");
    printf("      速率只涨 4 倍而不是无限涨 —— 因为噪声会吃掉电平间隔。\n");
    printf("      这就是为什么实际系统要在「电平数」和「抗噪」之间折中。\n");
    return 0;
}
